public final class ArmyBehaviors {
    public interface Behavior {
        boolean allows(int id);
        int choose(LivingEntity target,long now);
        void impact(SkillDefinition skill,int frame);
        void move(LivingEntity target,long now);
        default boolean canStart(int id,LivingEntity target){return true;}
        default void started(int id,LivingEntity target){}
        default void tick(long now){}
        default void died(DamageSource source){}
        default void tickDead(long now){}
        default void hookHit(LivingEntity target){}
        default void hurtAccepted(DamageSource source,boolean frontal){}
        default void hurtAccepted(DamageSource source,boolean frontal,float healthLost){hurtAccepted(source,frontal);}
        default boolean evade(DamageSource source){return false;}
        default boolean canInterrupt(){return true;}
        default boolean preventFatal(DamageSource source,float damage){return false;}
        default CompoundTag save(){return new CompoundTag();}
        default void load(CompoundTag tag){}
        default String animation(int id){return switch(id){case ArmySkills.BRACE->"brace";case ArmySkills.ROLL->"roll";
            case ArmySkills.GRAPPLE->"grapple";case ArmySkills.KNEE->"knee";case ArmySkills.DETONATE->"detonate";
            case ArmySkills.SCORPION_EMERGE->"emerge";case ArmySkills.SCORPION_SONG->"song";case ArmySkills.TREE_WAKE->"wake";case ArmySkills.TREE_ROOTS->"roots";case ArmySkills.TOAD_LEAP->"leap";case ArmySkills.TOAD_BURST->"burst";case ArmySkills.SKULL_BLOOD->"blood";case ArmySkills.PAPER_SHED->"shed";case ArmySkills.CHILD_CURSE->"curse";case ArmySkills.AXE_COUNTER->"counter";case ArmySkills.GHOST_PHASE->"phase";default->"attack";};}
    }
    static Behavior create(TemplateMob mob,TemplateMob.Kind kind){return switch(kind){
        case PALANQUIN->new PalanquinBehavior(mob);case YECHA->new YechaBehavior(mob);case CENTIPEDE->new CentipedeBehavior(mob);case BIXI->new BixiBehavior(mob);case DROWNER->new DrownerBehavior(mob);case BLIND_FISH->new BlindFishBehavior(mob);case LANTERN_BAT->new LanternBatBehavior(mob);case MINING_SPIDER->new MiningSpiderBehavior(mob);case BRONZE_SNAKE->new BronzeSnakeBehavior(mob);case CLOCKWORK_DOG->new ClockworkDogBehavior(mob);case STONE_GUARD->new StoneGuardBehavior(mob);case SERPENT->new WaterSerpentBehavior(mob);case SPEAR->new Spear(mob);case CROSSBOW->new Crossbow(mob);case SCOUT->new Scout(mob);
        case POWDER->new Powder(mob);case FLAG->new Flag(mob);case AXE_GUARD->new AxeGuard(mob);case GHOST->new Ghost(mob);case CORPSE->new Corpse(mob);case CHILD->new ShroudChild(mob);case PAPER->new PaperSwordsman(mob);case SKULL->new FlyingSkull(mob);case TOAD->new RedToad(mob);case TREE->new TreeSpirit(mob);case SCORPION->new SandScorpion(mob);default->null;};}

private static final class Ghost extends Base {
    boolean evadeReady;
    Ghost(TemplateMob mob){super(mob);}
    public boolean allows(int id){return id==ArmySkills.GHOST_THRUST||id==ArmySkills.GHOST_PHASE;}
    public boolean canStart(int id,LivingEntity target){return id!=ArmySkills.GHOST_PHASE||evadeReady;}
    public boolean canInterrupt(){return !mob.isPhased();}
    public int choose(LivingEntity target,long now){return ArmySkills.GHOST_THRUST;}
    public boolean evade(DamageSource source){
        if(source.is(DamageTypeTags.BYPASSES_INVULNERABILITY))return false;
        if(mob.isPhased())return true;
        long now=level().getGameTime();
        if(!(source.getDirectEntity() instanceof LivingEntity attacker)||source.getEntity()!=attacker
                ||!mob.validEnemy(attacker)||source.is(DamageTypeTags.IS_PROJECTILE)
                ||mob.distanceToSqr(attacker)>256||!mob.hasLineOfSight(attacker)
                ||!mob.attack().ready(ArmySkills.GHOST_PHASE,now)||mob.attack().state(now)==AttackState.STUN
                ||mob.getRandom().nextFloat()>=.35F)return false;
        Vec3 landing=phaseLanding(mob,attacker);if(landing==null)return false;
        evadeReady=true;mob.cancelAction();boolean started=mob.startSkill(ArmySkills.GHOST_PHASE,attacker);evadeReady=false;
        if(!started)return false;
        level().sendParticles(net.minecraft.core.particles.ParticleTypes.SOUL,mob.getX(),mob.getY()+.9,mob.getZ(),8,.2,.5,.2,.02);
        mob.teleportTo(landing.x,landing.y,landing.z);mob.setDeltaMovement(Vec3.ZERO);mob.setTarget(attacker);
        mob.playSound(SoundEvents.SOUL_ESCAPE,.6F,.8F);return true;
    }
    public void impact(SkillDefinition skill,int frame){
        if(skill.id()!=ArmySkills.GHOST_THRUST)return;
        for(var target:CombatGeometry.query(level(),mob.position(),mob.attack().direction(),CombatGeometry.Shape.STRIP,
                3.8,.4,30,1.6,e->mob.validEnemy(e)&&mob.hasLineOfSight(e))){
            target.invulnerableTime=0;
            if(target.hurt(mob.damageSources().indirectMagic(mob,mob),(float)mob.getAttributeValue(Attributes.ATTACK_DAMAGE)))
                target.addEffect(new MobEffectInstance(BlueprintEntities.SPIRIT_CHILL.get(),60,0),mob);
            if(!mob.isAlive()||mob.attack().current()!=skill)return;
        }
    }
}
/** Only two side directions and three floor heights; no unloaded chunk access or solid-wall crossing. */
static Vec3 phaseLanding(TemplateMob mob,LivingEntity attacker){
    var level=(ServerLevel)mob.level();
    Vec3 forward=attacker.getLookAngle().multiply(1,0,1).normalize();
    if(forward.lengthSqr()<.001)forward=mob.position().subtract(attacker.position()).multiply(1,0,1).normalize();
    if(forward.lengthSqr()<.001)return null;
    for(int side:new int[]{1,-1})for(int dy:new int[]{0,1,-1}){
        Vec3 candidate=attacker.position().add(-forward.z*3*side,dy,forward.x*3*side);
        var pos=net.minecraft.core.BlockPos.containing(candidate);
        candidate=new Vec3(candidate.x,pos.getY(),candidate.z);
        var box=mob.getType().getDimensions().makeBoundingBox(candidate.x,candidate.y,candidate.z);
        if(!level.hasChunkAt(pos)||!level.hasChunkAt(net.minecraft.core.BlockPos.containing(box.minX,box.minY,box.minZ))
                ||!level.hasChunkAt(net.minecraft.core.BlockPos.containing(box.maxX,box.maxY,box.maxZ))
                ||!level.getWorldBorder().isWithinBounds(box)||!level.getFluidState(pos).isEmpty()
                ||!com.dynasty.entity.DynastySpawnPlacement.hasStandingSpace(level,pos,box))continue;
        if(!level.getEntitiesOfClass(LivingEntity.class,box,e->e.isAlive()&&e instanceof com.dynasty.DynastyBossCombat.BarHolder).isEmpty())continue;
        var line=level.clip(new net.minecraft.world.level.ClipContext(mob.getEyePosition(),candidate.add(0,mob.getEyeHeight(),0),
            net.minecraft.world.level.ClipContext.Block.COLLIDER,net.minecraft.world.level.ClipContext.Fluid.NONE,mob));
        if(line.getType()==net.minecraft.world.phys.HitResult.Type.MISS)return candidate;
    }
    return null;
}

/** The same validation gates AI and operator/GameTest starts; no client can request a damage frame. */
public boolean startSkill(int id, LivingEntity target) {
    if (level().isClientSide || !isAlive() || isRemoved() || !allows(id)) return false;
    SkillDefinition base = TemplateSkills.byId(id);
    if (base == null || (id == ArmySkills.SCORPION_EMERGE && target == this ? false : id == TemplateSkills.POSSESSION ? !validSupport(target) : !validEnemy(target))) return false;
    double range = distanceTo(target);
    if (range < base.minRange() || range > (id == ArmySkills.AXE_COUNTER ? 40 : base.maxRange()) || id != ArmySkills.SCORPION_EMERGE && base.requiresSight() && !hasLineOfSight(target)) return false;
    if (id == TemplateSkills.ROCK_THROW && !onHighGround(target)) return false;
    if (army != null && !army.canStart(id,target)) return false;
    Vec3 direction = target.position().subtract(position()).multiply(1, 0, 1).normalize();
    if (direction.lengthSqr() < .0001) direction = getLookAngle().multiply(1, 0, 1).normalize();
    // A fuse uses real elapsed time, not attack speed: three consecutive close seconds.
    float speed = id != ArmySkills.DETONATE && id != ArmySkills.AXE_COUNTER && id != ArmySkills.CHILD_CURSE && id != ArmySkills.SKULL_DIVE && id != ArmySkills.SKULL_BLOOD && id != ArmySkills.TOAD_LEAP && id != ArmySkills.SERPENT_COIL && id != ArmySkills.SERPENT_BITE && id != ArmySkills.STONE_SLAM && id != ArmySkills.STONE_UPPERCUT && id != ArmySkills.DOG_BITE && id != ArmySkills.DOG_ALARM && kind != Kind.BRONZE_SNAKE && kind != Kind.MINING_SPIDER && kind != Kind.LANTERN_BAT && kind != Kind.BLIND_FISH && kind != Kind.DROWNER && kind != Kind.BIXI && kind != Kind.CENTIPEDE && kind != Kind.YECHA && kind != Kind.PALANQUIN && hasEffect(BlueprintEntities.BINGSHA_POSSESSION.get()) ? 1.3F : 1F;
    SkillDefinition effective = TemplateSkills.accelerated(base, speed);
    if (!attack.tryStart(effective, level().getGameTime(), position(), direction, target.getUUID())) return false;
    if(army!=null)army.started(id,target);
    entityData.set(SPEED, speed);
    coverUntil = 0;
    entityData.set(SKILL, id); entityData.set(START, attack.started()); entityData.set(PHASE, AttackState.WINDUP.ordinal());
    navigation.stop(); face(direction);
    if (id == TemplateSkills.POSSESSION) entityData.set(BUFF_TARGET, target.getId());
    if (id == TemplateSkills.POUNCE) {
        Vec3 towards = target.position().subtract(position()).multiply(1, 0, 1);
        leapDestination = position().add(towards.normalize().scale(Math.min(5.6, towards.length())));
    }
    BlueprintVisualEvent.start(this, effective, attack.origin(), attack.direction(), target.getId());
    playSound(kind == Kind.BEAST ? SoundEvents.FOX_AGGRO : kind == Kind.PRIEST ? SoundEvents.EVOKER_PREPARE_ATTACK : SoundEvents.PLAYER_ATTACK_SWEEP,
            .6F, kind == Kind.SHIELD ? .65F : 1F);
    return true;
}
private boolean allows(int id) {
    return switch (kind) {
        case SWORD -> id == TemplateSkills.SWORD_COMBO;
        case SHIELD -> id == TemplateSkills.SHIELD_COMBO;
        case PRIEST -> id == TemplateSkills.TALISMAN_VOLLEY || id == TemplateSkills.POSSESSION;
        case BEAST -> id == TemplateSkills.POUNCE || id == TemplateSkills.ROCK_THROW;
        default -> army != null && army.allows(id);
    };
}

public void interruptAttack(int stunTicks) {
    if (level().isClientSide || !isAlive()) return;
    if (army != null && !army.canInterrupt()) return;
    int duration=hasEffect(BlueprintEntities.JUNHUN_AURA.get())?Math.max(1,stunTicks/2):stunTicks;
    attack.stun(level().getGameTime(), duration); finishAction(); entityData.set(PHASE, AttackState.STUN.ordinal());
}
/** Cancel both the server clock and its tracked animation, including a failed follow-up start. */
void cancelAction() {
    if (level().isClientSide) return;
    attack.cancel(); finishAction(); entityData.set(PHASE, attack.state(level().getGameTime()).ordinal());
}
private void finishAction() {
    entityData.set(SKILL, 0); entityData.set(START, -1L); entityData.set(SPEED, 1F);
    syncHook(null,-1);
    if (linkUntil == 0) entityData.set(BUFF_TARGET, -1);
    BlueprintVisualEvent.cancel(this);
}
private void face(Vec3 direction) {
    if(kind==Kind.BRONZE_SNAKE&&(skillId()==ArmySkills.BRONZE_REAR_STAB||skillId()==ArmySkills.BRONZE_POISON))direction=direction.scale(-1);
    float yaw = (float)(Math.atan2(direction.z, direction.x) * 180 / Math.PI) - 90;
    setYRot(yaw); yBodyRot = yaw; yHeadRot = yaw;
}

@Override public boolean hurt(DamageSource source, float amount) {
    if (level().isClientSide) return false;
    if (amount > 0 && isAlive() && army != null && army.evade(source)) return false;
    Entity direct = source.getDirectEntity();
    boolean projectile = source.is(DamageTypeTags.IS_PROJECTILE) || direct instanceof Projectile;
    Vec3 sourcePosition = direct == null ? source.getSourcePosition() : direct.position();
    boolean frontal = sourcePosition != null && CombatGeometry.inFront(position(), getLookAngle(), sourcePosition, 120);
    if (kind == Kind.SHIELD && frontal) {
        if (projectile) {
            if (direct instanceof Projectile) direct.discard();
            playSound(SoundEvents.SHIELD_BLOCK, .7F, .7F); return false;
        }
        if (direct instanceof LivingEntity && source.getEntity() == direct) amount *= .2F;
    }
    if (!isAlive()) return false;
    if (kind == Kind.SWORD && formation && direct instanceof AbstractArrow) amount *= .8F;
    float before=getHealth();
    boolean damaged = super.hurt(source, amount);
    if (damaged && isAlive() && army != null) army.hurtAccepted(source, frontal, Math.max(0,before-getHealth()));
    if (damaged && isAlive() && attack.current() != null && attack.current().interruptible()
            && attack.state(level().getGameTime()) == AttackState.WINDUP && amount >= Math.max(3, getMaxHealth() * .08F))
        interruptAttack(10);
    return damaged;
}
public boolean preventPaperFatal(DamageSource source,float damage) {
    return kind==Kind.PAPER && !level().isClientSide && isAlive() && army.preventFatal(source,damage);
}

@Override public boolean canBeCollidedWith() { return kind == Kind.SHIELD && !isRemoved(); }
@Override public net.minecraft.world.entity.MobType getMobType() {
    return kind == Kind.CORPSE || kind == Kind.SKULL ? net.minecraft.world.entity.MobType.UNDEAD : super.getMobType();
}
public boolean isPhased() { return kind == Kind.GHOST && skillId() == ArmySkills.GHOST_PHASE && actionAge(0) < 6 && isAlive(); }
@Override public boolean canBeHitByProjectile() { return !isPhased() && (kind == Kind.SHIELD && !isRemoved() || super.canBeHitByProjectile()); }
@Override public boolean isPickable() { return !isPhased() && super.isPickable(); }
@Override public boolean isPushable() { return kind != Kind.GHOST && (kind!=Kind.TREE||treeAwake()) && super.isPushable(); }
